function v3_regression(out)
Simulink.fileGenControl('set','CacheFolder',fullfile(out,'cache','REGRESSION'),'CodeGenFolder',fullfile(out,'cache','REGRESSION','codegen'),'createDir',true);
% Re-run the frozen E2 MPC task after PID changes, with the exact same physical bank.
original=fullfile(out,'E2/cases/V2_S05_3');s=jsondecode(fileread(fullfile(original,'case_config.json')));s.group='REGRESSION';s.id='VR_MPC_ISOLATION';s.phase='regression';v3_run_case(s,out);folder=fullfile(out,'REGRESSION/cases',s.id);a=load(fullfile(original,'sim_output.mat'));b=load(fullfile(folder,'sim_output.mat'));ba=load(fullfile(original,'reference_bank.mat'));bb=load(fullfile(folder,'reference_bank.mat'));bank_equal=true;for key={'time','q_ref','omega_ref','tau_d','x0'},field=key{1};bank_equal=bank_equal && isequal(ba.(field),bb.(field));end
ta=a.r.states.Time(:);tb=b.r.states.Time(:);same_time=isequal(ta,tb);state_diff=inf;command_diff=inf;if same_time,state_diff=max(abs(squeeze(a.r.states.Data)-squeeze(b.r.states.Data)),[],'all');command_diff=max(abs(squeeze(a.r.commands.Data)-squeeze(b.r.commands.Data)),[],'all');end
e=struct('case_original','V2_S05_3','case_regression',s.id,'same_physical_reference',bank_equal,'same_time_grid',same_time,'max_state_difference',state_diff,'max_command_difference',command_diff,'passed',bank_equal && same_time && state_diff<1e-7 && command_diff<1e-7,'scope','Native MPC source untouched; exact E2 task replay after frozen PID integration. Concurrent wall times are not deterministic.');paper_json(fullfile(out,'reports/MPC_isolation_regression.json'),e);assert(e.passed,'v3:regression','MPC isolation replay differs');
end
